            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted">⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>
                        <a href="recipes/@Category/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link">← Back to categories</a>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private List<Recipe> recipes = new();
    private string CategoryDisplay => Category switch
    {
        "pasta" => "🍝 Pasta & Noodles",
        "salads" => "🥗 Salads & Bowls",
        "desserts" => "🍰 Desserts",
        _ => Category
    };

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipes/{category}/{id:int}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Not Found - RecipeHub</PageTitle>
    <h1>Recipe not found</h1>
}
else
{
    <PageTitle>@recipe.Title - RecipeHub</PageTitle>

    <h1>@recipe.Title</h1>
    <p class="text-muted">⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.TrimStart();
            if (text.Length > 2 && text[1] == '.' && char.IsDigit(text[0]))
                text = text[3..];
            <li>@text</li>
        }
    </ol>

    <h3>Rate this recipe</h3>
    <StarRating RecipeId="recipe.Id" />
}

<a href="recipes/@Category" class="btn btn-link mt-3">← Back to @Category</a>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-1">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-sm @(star <= selectedRating ? "btn-warning" : "btn-outline-secondary")"
                @onclick="() => Rate(star)"
                disabled="@hasRated">
            ★
        </button>
    }
    @if (hasRated)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selectedRating;
    private bool hasRated;

    private void Rate(int stars)
    {
        selectedRating = stars;
        hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

