        new Recipe { Id = 3, Title = "Caesar Salad", Category = "salads", Ingredients = "Romaine lettuce, croutons, parmesan, Caesar dressing, anchovies", Steps = "1. Wash and chop romaine\n2. Make dressing\n3. Toss with croutons and cheese", AverageRating = 3.8, RatingCount = 5 },
        new Recipe { Id = 4, Title = "Quinoa Buddha Bowl", Category = "salads", Ingredients = "Quinoa, chickpeas, avocado, sweet potato, tahini", Steps = "1. Cook quinoa\n2. Roast sweet potato and chickpeas\n3. Assemble bowl\n4. Drizzle with tahini", AverageRating = 4.0, RatingCount = 6 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "desserts", Ingredients = "Dark chocolate, butter, eggs, sugar, flour", Steps = "1. Melt chocolate and butter\n2. Whisk eggs and sugar\n3. Combine and pour into ramekins\n4. Bake 12 minutes at 220°C", AverageRating = 4.8, RatingCount = 15 },
        new Recipe { Id = 6, Title = "Apple Pie", Category = "desserts", Ingredients = "Apples, sugar, cinnamon, butter, pie crust", Steps = "1. Make pie crust\n2. Slice and season apples\n3. Fill crust and add top\n4. Bake 45 minutes at 190°C", AverageRating = 4.3, RatingCount = 10 },
    };

    private int _nextId = 7;

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalStars / recipe.RatingCount;
    }
}

